task.setup:
sim.user.config["user.name"] = "Anna Karimova";
sim.user.config["user.email"] = "anna@example.com";
sim.user.config["init.defaultBranch"] = "main";
sim.run(`mkdir portfolio && cd portfolio && git init
echo "<h1>Anna Karimova</h1>" > index.html
git add . && git commit -m "Add home page"
echo "body { margin: 0; }" > style.css
git add . && git commit -m "Add styles"
echo "<p>Frontend developer</p>" >> index.html
git commit -am "Add job title"
`, { quiet: true });
sim.createRemote("https://github.com/anna/portfolio.git");
sim.createRemote("https://github.com/aziz/notes.git", { writers: ["aziz"] });
sim.addUser("aziz", { name: "Aziz Rakhimov", email: "aziz@example.com", defaultBranch: "main" });
sim.run(`mkdir notes && cd notes && git init
echo "# Git notes" > README.md
git add . && git commit -m "Add README"
echo "git status - what is going on" > git.md
git add . && git commit -m "Add git commands"
echo "git log --oneline - short history" >> git.md
git commit -am "Add git log"
git remote add origin https://github.com/aziz/notes.git
git push -u origin main
`, { user: "aziz", quiet: true });
sim.run("cd portfolio", { quiet: true });

